CREATE DATABASE IF NOT EXISTS alumni_connect CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE alumni_connect;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('student','alumnus','bedrijf','organisator','mentor','beheerder') NOT NULL DEFAULT 'student', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `profiles` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `education` VARCHAR(500) NOT NULL, `graduation_year` VARCHAR(500) NOT NULL, `job` VARCHAR(500) NOT NULL, `skills` VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `opportunities` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `title` VARCHAR(500) NOT NULL, `company` VARCHAR(500) NOT NULL, `description` TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `events` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `title` VARCHAR(500) NOT NULL, `event_date` VARCHAR(500) NOT NULL, `location` VARCHAR(500) NOT NULL, `description` TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `registrations` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `event_id` INT NOT NULL, `status` VARCHAR(500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE, UNIQUE KEY unique_registration (owner_id,event_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `questions` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `title` VARCHAR(500) NOT NULL, `body` TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `answers` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `question_id` INT NOT NULL, `body` TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `news` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `title` VARCHAR(500) NOT NULL, `body` TEXT NOT NULL, `published` TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `matches` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `student_id` INT NOT NULL, `mentor_id` INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `feedback` (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, `student_id` INT NOT NULL, `portfolio_url` VARCHAR(500) NOT NULL, `body` TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
